import math

def control(o):
    h=o['hitch_deg']
    rig=o['rig']
    rear=rig['trailer_rear']
    pts=[]
    for name in ('direct','left_mirror','right_mirror'):
        v=o.get('views',{}).get(name)
        if not v: continue
        ox,oy=v['origin']
        for b,d in v.get('walls',[]):
            a=math.radians(b)
            x=ox+d*math.cos(a); y=oy+d*math.sin(a)
            if x < rear[0]-1 and x > rear[0]-12: pts.append((x,y))
    desired=0.0
    if pts:
        left=[y for x,y in pts if y>rear[1]+0.7]
        right=[y for x,y in pts if y<rear[1]-0.7]
        if left and right:
            center=(min(left)+max(right))/2
            desired=max(-12,min(12,(center-rear[1])*4))
    elif o['progress']['covered']<8:
        desired=5
    steer=max(-30,min(30,1.8*(h-desired)))
    return (steer,-0.8,170)

